import type { XFelModuleFactory } from './emscripten-types';

/**
 * Dynamically import the emscripten module generated by `make`
 * (build/xfel.js, wasm embedded as base64). Keeping this import dynamic
 * gives a clear error message when the wasm build is missing, instead
 * of breaking the whole page load.
 */
export async function loadXFelModuleFactory(): Promise<XFelModuleFactory> {
	try {
		// @ts-ignore — the emscripten build output has no bundled type declarations
		const mod = await import('../../../build/xfel.js');
		return mod.default as XFelModuleFactory;
	} catch (e) {
		if (e instanceof Error && e.name !== 'TypeError')
			throw e;
		throw new Error('wasm 模块未找到：请先在项目根目录运行 make，然后刷新页面（npm run dev / build 需要 build/xfel.js）');
	}
}
